var e={kind:`board`,caption:`客户端连上服务器、再由客户端主动断开（客户端 ISN = 1000，服务器 ISN = 5000）`,stepTitles:{0:`① 第一次握手`,1:`② 第二次握手`,2:`③ 第三次握手`,3:`④ 第一、二次挥手`,4:`⑤ 第三、四次挥手`},cols:2,regions:[{id:`client`,label:`客户端`},{id:`server`,label:`服务器`}],legend:[[`new`,`这一步发出的报文`]],frames:[{step:0,msg:null,boxes:{client:{tag:`CLOSED`,items:[{t:`初始序号 ISN = 1000`}]},server:{tag:`LISTEN`,items:[{t:`初始序号 ISN = 5000`}]}},calc:[[`服务器`,`调用 listen，等连接`],[`客户端`,`调用 connect，准备发 SYN`]],note:`服务器先调用 listen，处于 LISTEN 状态；客户端还没有连接（CLOSED）。为了好算，这里客户端的初始序号取 1000，服务器取 5000（实际是随机的）。`},{step:0,msg:`客户端 ──▶ 服务器　SYN，seq=1000`,boxes:{client:{tag:`SYN_SENT`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:`new`}],hot:!0},server:{tag:`LISTEN`,items:[{t:`初始序号 ISN = 5000`}],hot:!1}},calc:[[`客户端`,`CLOSED → SYN_SENT`],[`服务器`,`LISTEN（不变）`]],note:`客户端发 SYN（seq=1000，1000 是随机选的初始序号 ISN），进入 SYN_SENT。SYN 不带数据，但占 1 个序号，所以客户端下一个要发的序号变成 1001。`},{step:1,msg:`服务器 ──▶ 客户端　SYN+ACK，seq=5000，ack=1001`,boxes:{client:{tag:`SYN_SENT`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null}],hot:!1},server:{tag:`SYN_RCVD`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:`new`}],hot:!0}},calc:[[`客户端`,`SYN_SENT（不变）`],[`服务器`,`LISTEN → SYN_RCVD`]],note:`服务器回 SYN+ACK：seq=5000 是服务器自己的初始序号，ack=1001 表示「1000 收到了，下次从 1001 发」。服务器进入 SYN_RCVD。`},{step:2,msg:`客户端 ──▶ 服务器　ACK，seq=1001，ack=5001`,boxes:{client:{tag:`ESTABLISHED`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:`new`}],hot:!0},server:{tag:`SYN_RCVD`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null}],hot:!1}},calc:[[`客户端`,`SYN_SENT → ESTABLISHED`],[`服务器`,`SYN_RCVD（不变）`]],note:`客户端回 ACK：seq=1001，ack=5001（确认了服务器的 SYN）。客户端进入 ESTABLISHED。这个 ACK 已经可以带数据。`},{step:2,msg:null,boxes:{client:{tag:`ESTABLISHED`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null}],hot:!1},server:{tag:`ESTABLISHED`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null}],hot:!0}},calc:[[`客户端`,`ESTABLISHED（不变）`],[`服务器`,`SYN_RCVD → ESTABLISHED`]],note:`服务器收到 ACK，也进入 ESTABLISHED。三次握手完成：双方都确认了对方的初始序号。`},{step:3,msg:`客户端 ──▶ 服务器　FIN+ACK，seq=1001，ack=5001`,boxes:{client:{tag:`FIN_WAIT_1`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:`new`}],hot:!0},server:{tag:`ESTABLISHED`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null}],hot:!1}},calc:[[`客户端`,`ESTABLISHED → FIN_WAIT_1`],[`服务器`,`ESTABLISHED（不变）`]],note:`客户端主动关闭：发 FIN（同时带 ACK），seq=1001，进入 FIN_WAIT_1，意思是「我不再发数据了」。FIN 也占 1 个序号。`},{step:3,msg:`服务器 ──▶ 客户端　ACK，seq=5001，ack=1002`,boxes:{client:{tag:`FIN_WAIT_1`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:null}],hot:!1},server:{tag:`CLOSE_WAIT`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null},{t:`发出：ACK，seq=5001，ack=1002`,st:`new`}],hot:!0}},calc:[[`客户端`,`FIN_WAIT_1（不变）`],[`服务器`,`ESTABLISHED → CLOSE_WAIT`]],note:`服务器回 ACK，ack=1002，进入 CLOSE_WAIT。此时服务器还能继续发没发完的数据（半关闭）。`},{step:3,msg:null,boxes:{client:{tag:`FIN_WAIT_2`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:null}],hot:!0},server:{tag:`CLOSE_WAIT`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null},{t:`发出：ACK，seq=5001，ack=1002`,st:null}],hot:!1}},calc:[[`客户端`,`FIN_WAIT_1 → FIN_WAIT_2`],[`服务器`,`CLOSE_WAIT（不变）`]],note:`客户端收到这个 ACK，进入 FIN_WAIT_2，等服务器那边也发 FIN。`},{step:4,msg:`服务器 ──▶ 客户端　FIN+ACK，seq=5001，ack=1002`,boxes:{client:{tag:`FIN_WAIT_2`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:null}],hot:!1},server:{tag:`LAST_ACK`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null},{t:`发出：ACK，seq=5001，ack=1002`,st:null},{t:`发出：FIN+ACK，seq=5001，ack=1002`,st:`new`}],hot:!0}},calc:[[`客户端`,`FIN_WAIT_2（不变）`],[`服务器`,`CLOSE_WAIT → LAST_ACK`]],note:`服务器程序调用 close，发 FIN（带 ACK），seq=5001，ack=1002，进入 LAST_ACK。`},{step:4,msg:`客户端 ──▶ 服务器　ACK，seq=1002，ack=5002`,boxes:{client:{tag:`TIME_WAIT`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:null},{t:`发出：ACK，seq=1002，ack=5002`,st:`new`}],hot:!0},server:{tag:`LAST_ACK`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null},{t:`发出：ACK，seq=5001，ack=1002`,st:null},{t:`发出：FIN+ACK，seq=5001，ack=1002`,st:null}],hot:!1}},calc:[[`客户端`,`FIN_WAIT_2 → TIME_WAIT`],[`服务器`,`LAST_ACK（不变）`]],note:`客户端回 ACK：seq=1002，ack=5002，进入 TIME_WAIT。`},{step:4,msg:null,boxes:{client:{tag:`TIME_WAIT`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:null},{t:`发出：ACK，seq=1002，ack=5002`,st:null}],hot:!1},server:{tag:`CLOSED`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null},{t:`发出：ACK，seq=5001，ack=1002`,st:null},{t:`发出：FIN+ACK，seq=5001，ack=1002`,st:null}],hot:!0}},calc:[[`客户端`,`TIME_WAIT（不变）`],[`服务器`,`LAST_ACK → CLOSED`]],note:`服务器收到最后这个 ACK，进入 CLOSED。`},{step:4,msg:null,boxes:{client:{tag:`CLOSED`,items:[{t:`初始序号 ISN = 1000`},{t:`发出：SYN，seq=1000`,st:null},{t:`发出：ACK，seq=1001，ack=5001`,st:null},{t:`发出：FIN+ACK，seq=1001，ack=5001`,st:null},{t:`发出：ACK，seq=1002，ack=5002`,st:null}],hot:!0},server:{tag:`CLOSED`,items:[{t:`初始序号 ISN = 5000`},{t:`发出：SYN+ACK，seq=5000，ack=1001`,st:null},{t:`发出：ACK，seq=5001，ack=1002`,st:null},{t:`发出：FIN+ACK，seq=5001，ack=1002`,st:null}],hot:!1}},calc:[[`客户端`,`TIME_WAIT → CLOSED`],[`服务器`,`CLOSED（不变）`]],note:`客户端在 TIME_WAIT 等满 2MSL 才进入 CLOSED：万一最后的 ACK 丢了，服务器会重发 FIN，客户端还能再回一次；也让这条连接的旧报文在网络里消失。演示结束。`}]};export{e as default};